<script setup lang="ts">import type {Point} from '../types/domain';import {fixed} from '../utils/format';import {rangeLabels} from '../constants/enums';defineProps<{rows:Point[];xUnit?:string;yUnit?:string;analysisUnit?:string}>()</script><template><div class="table-wrap"><table><thead><tr><th>配对编号</th><th>量程</th><th>X<small v-if="xUnit"> / {{xUnit}}</small></th><th>Y<small v-if="yUnit"> / {{yUnit}}</small></th><th>差值 y−x<small v-if="analysisUnit"> / {{analysisUnit}}</small></th><th>界限外</th></tr></thead><tbody><tr v-for="p in rows" :key="p.pair_id"><td>{{p.pair_id}}</td><td>{{rangeLabels[p.range_label]}}</td><td>{{fixed(p.x_raw??p.x)}}</td><td>{{fixed(p.y_raw??p.y)}}</td><td>{{fixed(p.difference??p.y-p.x)}}</td><td>{{p.outside_loa?'待复核':'—'}}</td></tr></tbody></table></div></template>
